#!/usr/bin/env python3
"""gen_srcs.py -- source lists of the vendored C libraries, read out of their
pinned release archives.

    python3 third_party/gen_srcs.py aws-lc  <aws-lc-X.tar.gz>   [--check]
    python3 third_party/gen_srcs.py s2n-tls <s2n-tls-X.tar.gz>  [--check]

Writes third_party/<library>/srcs.bzl. With --check it writes nothing and
exits 1 when the committed file differs from what the archive gives (the
drift check of tools/build/checks/c_libs_checks.sh), naming the first lines
that differ.

The lists are the ones the library's own CMake build compiles for the
configuration third_party/<library>/BUCK builds (see the comments in each
section below); every list is read from the archive's CMakeLists.txt, and
every file it names must exist in the archive. The header lists are the
closure of the `#include`s of the listed sources, so a compile action gets
exactly the headers its sources can reach.
"""

import os
import re
import sys
import tarfile

HERE = os.path.dirname(os.path.abspath(__file__))


class Archive:
    def __init__(self, path):
        with tarfile.open(path) as tar:
            members = [m for m in tar.getmembers() if m.isfile()]
            roots = {m.name.split("/", 1)[0] for m in members}
            if len(roots) != 1:
                sys.exit("gen_srcs: {} has {} top-level directories, expected one".format(path, len(roots)))
            self.prefix = roots.pop()
            self.files = {}
            for m in members:
                rel = m.name[len(self.prefix) + 1:]
                if rel.endswith((".c", ".h", ".S", ".txt", ".flags", ".inc")):
                    self.files[rel] = tar.extractfile(m).read().decode("utf-8", "replace")
            self.all = {m.name[len(self.prefix) + 1:] for m in members}

    def text(self, rel):
        if rel not in self.files:
            sys.exit("gen_srcs: {} is not in the archive".format(rel))
        return self.files[rel]

    def need(self, rel):
        if rel not in self.all:
            sys.exit("gen_srcs: the CMake lists name {}, which is not in the archive".format(rel))
        return rel


def cmake_block(text, anchor, what):
    """The whitespace-separated words after regex `anchor`, up to the next `)`."""
    m = re.search(anchor, text)
    if not m:
        sys.exit("gen_srcs: no {} in the CMake lists (pattern {!r}); update gen_srcs.py".format(what, anchor))
    words = []
    for line in text[m.end():].splitlines():
        line = line.split("#", 1)[0]
        end = line.find(")")
        words.extend((line if end < 0 else line[:end]).split())
        if end >= 0:
            return words
    sys.exit("gen_srcs: the {} list is not closed".format(what))


def only_files(words, allowed_vars, what):
    out = []
    for w in words:
        if w.startswith("${"):
            if w not in allowed_vars:
                sys.exit("gen_srcs: {} names {}, which gen_srcs.py does not handle".format(what, w))
            continue
        out.append(w)
    return out


INCLUDE_RE = re.compile(r'^\s*#\s*include\s*([<"])([^>"]+)[>"]', re.M)


def include_closure(arc, sources, roots):
    """Every archive file reachable from `sources` through #include.

    A quoted include resolves against the including file's directory first,
    then against `roots` (the -I directories); an angle include against
    `roots` only. An include that resolves nowhere is a system header (or
    sits behind an #if this configuration does not take) and is skipped.
    """
    seen = set()
    todo = list(sources)
    while todo:
        f = todo.pop()
        for kind, name in INCLUDE_RE.findall(arc.files.get(f, "")):
            cands = []
            if kind == '"':
                cands.append(os.path.normpath(os.path.join(os.path.dirname(f), name)))
            cands.extend(os.path.normpath(os.path.join(r, name)) for r in roots)
            for c in cands:
                if c in arc.files:
                    if c not in seen:
                        seen.add(c)
                        todo.append(c)
                    break
    return seen


def bzl_list(name, items, comment):
    lines = [""] + [("# " + l) if l else "#" for l in comment.splitlines()]
    lines.append("{} = [".format(name))
    lines.extend('    "{}",'.format(i) for i in items)
    lines.append("]")
    return lines


def bzl_dict(name, items, comment):
    lines = [""] + [("# " + l) if l else "#" for l in comment.splitlines()]
    lines.append("{} = {{".format(name))
    lines.extend('    "{}": "{}",'.format(k, v) for k, v in sorted(items.items()))
    lines.append("}")
    return lines


def header(library, arc):
    return [
        "# Generated by third_party/gen_srcs.py from the {} archive ({}); do not edit.".format(library, arc.prefix),
        "# Regenerate: python3 third_party/gen_srcs.py {} <archive>. The drift check of".format(library),
        "# tools/build/checks/c_libs_checks.sh fails when this file and the archive disagree.",
    ]


# ---- aws-lc ----------------------------------------------------------------
#
# The configuration: libcrypto only (no libssl, no tool), not FIPS, a Release
# build without Perl or Go -- the pre-generated assembly and err_data.c that
# the archive ships under generated-src/ -- and Dilithium off (the CMake
# defaults for everything else).

def aws_lc(arc):
    crypto_cmake = arc.text("crypto/CMakeLists.txt")
    fips_cmake = arc.text("crypto/fipsmodule/CMakeLists.txt")

    crypto_c = only_files(
        cmake_block(crypto_cmake, r"add_library\(\s*crypto_objects\s+OBJECT\b", "crypto_objects library"),
        {"${DILITHIUM_SOURCES}", "${CRYPTO_ARCH_SOURCES}", "${CRYPTO_ARCH_OBJECTS}"},
        "crypto_objects",
    )
    # err_data.c is written into the build directory: by Go, or (without
    # Go) copied from the shipped generated-src/err_data.c.
    crypto_c = [arc.need("generated-src/err_data.c" if f == "err_data.c" else "crypto/" + f) for f in crypto_c]

    def arch_sources(arch, gen_dir, anchor, what):
        out = []
        for f in cmake_block(crypto_cmake, anchor, what):
            f = f.replace("${ASM_EXT}", "S")
            gen = "generated-src/{}/crypto/{}".format(gen_dir, f)
            out.append(gen if gen in arc.all else arc.need("crypto/" + f))
        return out

    # x86_64: the branch taken when the assembler handles AVX (it does).
    crypto_asm_x86_64 = arch_sources(
        "x86_64", "linux-x86_64",
        r'if\(ARCH STREQUAL "x86_64"\)\s*if\(MY_ASSEMBLER_IS_TOO_OLD_FOR_AVX\)[\s\S]*?else\(\)\s*set\(\s*CRYPTO_ARCH_SOURCES\b',
        "x86_64 CRYPTO_ARCH_SOURCES",
    )
    crypto_asm_aarch64 = [f.replace("${ASM_EXT}", "S") for f in cmake_block(
        crypto_cmake, r'if\(ARCH STREQUAL "aarch64"\)\s*set\(\s*CRYPTO_ARCH_SOURCES\b', "aarch64 CRYPTO_ARCH_SOURCES")]

    bcm_c = only_files(
        cmake_block(fips_cmake, r"else\(\)\s*set\(BCM_ASM_OBJECTS \"\"\)[\s\S]*?add_library\(\s*fipsmodule\s+OBJECT\b",
                    "non-FIPS fipsmodule library"),
        {"${BCM_ASM_SOURCES}", "${BCM_ASM_OBJECTS}"},
        "fipsmodule",
    )
    bcm_c = [arc.need("crypto/fipsmodule/" + f) for f in bcm_c]

    def bcm_asm(arch):
        words = cmake_block(fips_cmake, r'if\(ARCH STREQUAL "{}"\)\s*set\(\s*BCM_ASM_SOURCES\b'.format(arch),
                            arch + " BCM_ASM_SOURCES")
        return [w.replace("${ASM_EXT}", "S") for w in words]

    bcm_asm_x86_64 = [arc.need("generated-src/linux-x86_64/crypto/fipsmodule/" + f) for f in bcm_asm("x86_64")]
    bcm_asm_aarch64 = bcm_asm("aarch64")

    s2n_common = cmake_block(fips_cmake, r"set\(\s*S2N_BIGNUM_ASM_SOURCES\b", "S2N_BIGNUM_ASM_SOURCES")
    s2n_x86_64 = cmake_block(
        fips_cmake, r'if\(ARCH STREQUAL "x86_64"\)\s*#[^\n]*[\s\S]*?list\(APPEND S2N_BIGNUM_ASM_SOURCES\b',
        "x86_64 S2N_BIGNUM_ASM_SOURCES")
    s2n_asm_x86_64 = [arc.need("third_party/s2n-bignum/x86_att/" + f) for f in s2n_common + s2n_x86_64]

    public = sorted(f for f in arc.all if f.startswith("include/openssl/") and f.endswith(".h"))
    roots = ["include", "third_party/s2n-bignum/include"]
    sources = crypto_c + crypto_asm_x86_64 + bcm_c + bcm_asm_x86_64 + s2n_asm_x86_64
    private = {}
    for f in sorted(include_closure(arc, sources, roots)):
        if f.startswith("include/"):
            if f not in public:
                sys.exit("gen_srcs: {} is reached through #include but is not a public header".format(f))
            continue
        key = f[len(roots[1]) + 1:] if f.startswith(roots[1] + "/") else f
        private[key] = f

    out = header("aws-lc", arc)
    out += bzl_list("CRYPTO_SRCS", crypto_c,
                    "crypto/CMakeLists.txt: add_library(crypto_objects); err_data.c is the shipped\ngenerated-src/err_data.c.")
    out += bzl_list("CRYPTO_ASM_X86_64", crypto_asm_x86_64,
                    "crypto/CMakeLists.txt: CRYPTO_ARCH_SOURCES for x86_64 (an assembler with AVX),\n"
                    "from generated-src/linux-x86_64 when shipped there.")
    out += bzl_list("BCM_SRCS", bcm_c, "crypto/fipsmodule/CMakeLists.txt: the non-FIPS add_library(fipsmodule).")
    out += bzl_list("BCM_ASM_X86_64", bcm_asm_x86_64,
                    "crypto/fipsmodule/CMakeLists.txt: BCM_ASM_SOURCES for x86_64.")
    out += bzl_list("S2N_BIGNUM_ASM_X86_64", s2n_asm_x86_64,
                    "crypto/fipsmodule/CMakeLists.txt: S2N_BIGNUM_ASM_SOURCES for x86_64 (compiled\n"
                    "with S2N_BN_HIDE_SYMBOLS and third_party/s2n-bignum/include on the path).")
    out += bzl_list("CRYPTO_ASM_AARCH64", crypto_asm_aarch64,
                    "Not built yet: CRYPTO_ARCH_SOURCES for aarch64, relative to\n"
                    "generated-src/<linux-aarch64 | ios-aarch64>/crypto/ (or crypto/).")
    out += bzl_list("BCM_ASM_AARCH64", bcm_asm_aarch64,
                    "Not built yet: BCM_ASM_SOURCES for aarch64, relative to\n"
                    "generated-src/<linux-aarch64 | ios-aarch64>/crypto/fipsmodule/.")
    out += bzl_list("PUBLIC_HEADERS", public, "Every public header, include/openssl/**.h.")
    out += bzl_dict("PRIVATE_HEADERS", private,
                    "The other files the sources above #include, keyed by the name they are\n"
                    "included by from an -I directory (the archive path when included relatively).")
    return out


# ---- s2n-tls ---------------------------------------------------------------
#
# The library's sources are CMake GLOBs: crypto/*.c, error/*.c, stuffer/*.c,
# tls/**/*.c and utils/*.c. The feature probes are tests/features/*.c, each
# compiled with GLOBAL.flags and its own <probe>.flags.

S2N_GLOBS = [("crypto/", False), ("error/", False), ("stuffer/", False), ("tls/", True), ("utils/", False)]


def s2n_tls(arc):
    cmake = arc.text("CMakeLists.txt")
    for d, recursive in S2N_GLOBS:
        pat = r'file\(GLOB{} {}_SRC "{}\*\.c"\)'.format(
            "_RECURSE" if recursive else "", d.rstrip("/").upper(), d)
        if not re.search(pat, cmake):
            sys.exit("gen_srcs: s2n-tls CMakeLists.txt no longer globs {}*.c the way gen_srcs.py expects".format(d))
    if not re.search(r"(?i)file\(GLOB FEATURE_SRCS \"\$\{CMAKE_CURRENT_LIST_DIR\}/tests/features/\*\.c\"\)", cmake):
        sys.exit("gen_srcs: s2n-tls feature probes are no longer tests/features/*.c")

    def globbed(d, recursive):
        out = []
        for f in arc.all:
            if f.startswith(d) and f.endswith(".c"):
                if recursive or "/" not in f[len(d):]:
                    out.append(f)
        return out

    srcs = sorted(f for d, r in S2N_GLOBS for f in globbed(d, r))
    roots = [".", "api"]
    private = {f: f for f in include_closure(arc, srcs, roots) if not f.startswith("api/")}
    public = sorted(f for f in arc.all if f.startswith("api/") and f.endswith(".h"))

    def flags(name):
        return " ".join(arc.text("tests/features/{}.flags".format(name)).split())

    probes = {}
    for f in sorted(arc.all):
        m = re.fullmatch(r"tests/features/([A-Z0-9_]+)\.c", f)
        if m:
            probes[m.group(1)] = flags(m.group(1))

    out = header("s2n-tls", arc)
    out += bzl_list("SRCS", srcs, "The library's sources (the CMake GLOBs).")
    out += bzl_list("PUBLIC_HEADERS", public, "The public API, api/**.h (included as <s2n.h>, <s2n/unstable/...>).")
    out += bzl_dict("PRIVATE_HEADERS", private,
                    "The other headers the sources #include, by their path from the repository\n"
                    "root (the root is on the include path).")
    out += ["", "# tests/features/GLOBAL.flags, passed to every probe.",
            'PROBE_GLOBAL_FLAGS = "{}"'.format(flags("GLOBAL"))]
    out += bzl_dict("PROBES", probes, "Each feature probe, tests/features/<name>.c, and its <name>.flags.")
    return out


LIBRARIES = {"aws-lc": aws_lc, "s2n-tls": s2n_tls}


def main(argv):
    args = [a for a in argv if a != "--check"]
    check = len(args) != len(argv)
    if len(args) != 2 or args[0] not in LIBRARIES:
        sys.exit("usage: gen_srcs.py {{{}}} <archive> [--check]".format(" | ".join(sorted(LIBRARIES))))
    library, archive = args
    text = "\n".join(LIBRARIES[library](Archive(archive))) + "\n"
    path = os.path.join(HERE, library, "srcs.bzl")
    if not check:
        with open(path, "w") as f:
            f.write(text)
        print("gen_srcs: wrote {} ({} lines)".format(path, text.count("\n")))
        return 0
    try:
        with open(path) as f:
            have = f.read()
    except OSError:
        have = ""
    if have == text:
        print("gen_srcs: {} matches {}".format(os.path.relpath(path), os.path.basename(archive)))
        return 0
    want_lines, have_lines = text.splitlines(), have.splitlines()
    diff = [l for l in want_lines if l not in set(have_lines)][:3] + \
           ["-" + l for l in have_lines if l not in set(want_lines)][:3]
    print("gen_srcs: {} differs from what {} gives: {}".format(
        os.path.relpath(path), os.path.basename(archive), " | ".join(diff) or "order or whitespace"))
    return 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
